from collections import defaultdict

def find_regions(grid, target_color):
    """Find all connected regions of a target color"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color and (r,c) not in visited:
                region = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    # Check neighbors
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == target_color and (nr, nc) not in visited:
                                stack.append((nr, nc))
                regions.append(region)
    return regions

# Find all non-background (non-3) colors
non_bg_colors = set()
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] != 3:
            non_bg_colors.add(grid[r][c])

print(f"Non-background colors: {sorted(non_bg_colors)}")
for color in sorted(non_bg_colors):
    regions = find_regions(grid, color)
    print(f"\nColor {color}: {len(regions)} regions")
    for i, region in enumerate(regions):
